inline std::string_view gamePanelMessageKeyName(GamePanelMessageKey key){
    static constexpr std::array<std::string_view,gamePanelMessageKeyCount> names={{"game.panel.invalid_target","game.panel.invalid_debounce","game.panel.invalid_poll","game.panel.invalid_age","game.panel.saved","game.panel.save_failed","game.panel.short_title","game.panel.short_resize","game.panel.short_keys","game.panel.footer_edit","game.panel.footer_review","game.panel.footer_browse","game.panel.title","game.panel.unsaved_suffix","game.panel.edit_keys","game.panel.leave_title","game.panel.leave_keys","game.panel.review_heading","game.panel.next_parent_start","game.panel.native_unavailable","game.panel.non_off_refusal","game.panel.frozen_heading","game.panel.effective_unavailable_heading","game.panel.no_session","game.panel.scope_unknown","game.panel.coexist_qualification","game.panel.current_frozen","game.panel.end_marker","game.panel.effective_unavailable","game.panel.no_session_compact","game.panel.configured_only","game.panel.exact_basename","game.panel.local_defaults"}};
    const auto index=static_cast<std::size_t>(key);return index<names.size()?names[index]:std::string_view{};
}
inline LocalizedMessage gamePanelMessage(std::string_view language,GamePanelMessageKey key){
    const auto index=static_cast<std::size_t>(key);if(index>=gamePanelMessageKeyCount)return {};
    const auto &source=gamePanelLocalePacks()[0];const auto *selected=&source;for(const auto &pack:gamePanelLocalePacks())if(pack.id==language){selected=&pack;break;}
    if(selected->id!=language||!validTemplateTranslation(source.messages[index],selected->messages[index]))return {source.messages[index],source.id,source.review,true,false};
    return {selected->messages[index],selected->id,selected->review,false,selected->rtl};
}
inline std::string gamePanelEnglish(GamePanelMessageKey key){return std::string(gamePanelMessage("en",key).text);}
